package common

import "encoding/hex"

var G_Abis = make(map[string]string)

func InitAbiFile(){

var files = make(map[string]string)

	files["SPL"] = ""

	files["ERC721"] = ""

	files["ERC20"] = ""



	for key, value := range files {
		tmp, _ := hex.DecodeString(value)
		G_Abis[key] = string(tmp)
	}

	files = nil
}

